// One-shot path migration script: operations/command/records/ → operations/command/endeavor/records/
// Excludes historical append-only artifacts and the installed .claude/ mirror (will be regenerated).

const fs = require('fs');
const path = require('path');

const OLD = 'operations/command/records';
const NEW = 'operations/command/endeavor/records';

const EXCLUDE_PREFIXES = [
  '.claude/',
  'operations/engineering/records/observations/archive/',
  'operations/engineering/records/session-state/history/',
  'operations/engineering/records/session-state/sessions/',
  'operations/engineering/records/sessions/',
  'operations/engineering/records/events/',
  'operations/engineering/records/tool-calls.jsonl',
  'operations/engineering/records/observations/observations.jsonl',
  'operations/engineering/records/session-state/bash-audit.jsonl',
  'operations/engineering/records/memory/project_theory-to-implementation-roadmap.md',
  'knowledge-graph.json',
  'operations/engineering/records/operations-graph.json',
  '.git/',
  'node_modules/',
  'library/triage/',
];

const INCLUDE_EXTS = new Set(['.js', '.ts', '.rs', '.md', '.json']);

let filesChanged = 0;
let occurrencesReplaced = 0;

function shouldSkip(relPath) {
  return EXCLUDE_PREFIXES.some(p => relPath.startsWith(p));
}

function walk(dir, cb) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    const rel = path.relative(process.cwd(), full);
    if (shouldSkip(rel)) continue;
    if (entry.isDirectory()) {
      walk(full, cb);
    } else if (entry.isFile()) {
      const ext = path.extname(entry.name);
      if (INCLUDE_EXTS.has(ext)) cb(full, rel);
    }
  }
}

walk(process.cwd(), (full, rel) => {
  const content = fs.readFileSync(full, 'utf8');
  if (!content.includes(OLD)) return;
  // Use negative lookahead to avoid matching if already has /endeavor/
  const next = content.split(OLD + '/').join(NEW + '/');
  const count = (content.match(new RegExp(OLD.replace(/[/.]/g, '\\$&') + '\\/', 'g')) || []).length;
  if (next === content) return;
  fs.writeFileSync(full, next);
  filesChanged += 1;
  occurrencesReplaced += count;
  process.stderr.write(`[update] ${rel}: ${count} refs\n`);
});

console.log(`\nChanged ${filesChanged} files, replaced ${occurrencesReplaced} refs total.`);
"}

