// Second-pass path migration: path.join(X, 'command', 'records', ...) → 'command', 'endeavor', 'records'
const fs = require('fs');
const path = require('path');

const EXCLUDE_PREFIXES = [
  '.claude/',
  'operations/engineering/records/observations/archive/',
  'operations/engineering/records/session-state/history/',
  'operations/engineering/records/session-state/sessions/',
  'operations/engineering/records/sessions/',
  'operations/engineering/records/events/',
  '.git/',
  'node_modules/',
  'library/triage/',
];

const INCLUDE_EXTS = new Set(['.js', '.ts', '.rs']);

let filesChanged = 0;
function shouldSkip(relPath) {
  return EXCLUDE_PREFIXES.some(p => relPath.startsWith(p));
}
function walk(dir, cb) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    const rel = path.relative(process.cwd(), full);
    if (shouldSkip(rel)) continue;
    if (entry.isDirectory()) walk(full, cb);
    else if (entry.isFile() && INCLUDE_EXTS.has(path.extname(entry.name))) cb(full, rel);
  }
}

// Match 'command', 'records' and "command", "records" — with endeavor not yet inserted
const pattern = /(['"])command\1(\s*,\s*)(['"])records\3/g;

walk(process.cwd(), (full, rel) => {
  const content = fs.readFileSync(full, 'utf8');
  if (!/(['"])command\1(\s*,\s*)(['"])records\3/.test(content)) return;
  const next = content.replace(pattern, (m, q1, comma, q2) => `${q1}command${q1}${comma}${q2}endeavor${q2}${comma}${q2}records${q2}`);
  if (next === content) return;
  fs.writeFileSync(full, next);
  filesChanged += 1;
  process.stderr.write(`[update2] ${rel}\n`);
});

console.log(`Changed ${filesChanged} files.`);
"}

